import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String args[]) throws IOException {
        Scanner fi = new Scanner(System.in);
        PrintWriter fo = new PrintWriter(System.out);
        int w = fi.nextInt(), m = fi.nextInt(), res = 1;
        while (m != 0){
            int tmp = m % w;
            if (tmp == w - 1 && tmp != 1) m = (m + 1) / w;
            else 
                if (tmp == 1) m /= w;
                else
                    if (tmp != 0){
                        res = 0;
                        break;
                    }
                    else m /= w;
        }
        if (res == 1) fo.print("YES");
        else fo.print("NO");
        fi.close();
        fo.close();
    }
}
